using System.Windows.Controls;using LibraryManager.Services;namespace LibraryManager.Views;public partial class BackupView:UserControl{public BackupView(){InitializeComponent();var p=VH.Page(Root,"پشتیبان‌گیری");p.Children.Add(new System.Windows.Controls.TextBlock{Text="مسیر پشتیبان: "+BackupService.BackupDir,Margin=new System.Windows.Thickness(8)});var g=VH.Table(p,BackupService.Files().Select(x=>new{نام=x.Name,حجم=(x.Length/1024)+" KB",تاریخ=x.CreationTime}).ToList());p.Children.Add(VH.Btn("پشتیبان‌گیری دستی",(s,e)=>{try{var path=System.IO.Path.Combine(BackupService.BackupDir,"Library_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".bak");BackupService.Backup(path);g.ItemsSource=BackupService.Files().Select(x=>new{نام=x.Name,حجم=(x.Length/1024)+" KB",تاریخ=x.CreationTime}).ToList();System.Windows.MessageBox.Show("پشتیبان ذخیره شد: "+path);}catch(Exception ex){VH.Error(ex);}}));p.Children.Add(new System.Windows.Controls.TextBlock{Text="برای بازیابی، فایل پشتیبان (.bak) را در مسیر Data\\LibraryManager.db کپی کنید (و فایل‌های .db-wal/.db-shm را حذف کنید).",Margin=new System.Windows.Thickness(8),TextWrapping=System.Windows.TextWrapping.Wrap});}}